mapper.select:
SELECT t.*, g.goods_name, w1.warehouse_name as from_warehouse_name, w2.warehouse_name as to_warehouse_name, u.real_name as operator_name FROM biz_stock_transfer t INNER JOIN biz_goods g ON t.goods_id = g.id INNER JOIN biz_warehouse w1 ON t.from_warehouse_id = w1.id INNER JOIN biz_warehouse w2 ON t.to_warehouse_id = w2.id LEFT JOIN sys_user u ON t.operator_id = u.id WHERE 1=1
AND t.goods_id = #{goodsId}
ORDER BY t.create_time DESC
